<div id="delivery-loading" hidden role="status" aria-live="polite" class="fixed inset-0 z-50 bg-white/70 p-6 backdrop-blur-[1px]"><span class="sr-only">Loading shipments</span><div class="mx-auto mt-28 max-w-5xl space-y-4 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div class="h-5 w-44 animate-pulse rounded bg-slate-200"></div>@for($i=0;$i<5;$i++)<div class="h-12 animate-pulse rounded-lg bg-slate-100"></div>@endfor</div></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{
  const rows=[...document.querySelectorAll('[data-shipment-row]')];
  const search=document.querySelector('#delivery-filters input[name="search"]');
  const from=document.querySelector('#delivery-filters input[name="from"]');
  const to=document.querySelector('#delivery-filters input[name="to"]');
  const empty=document.getElementById('delivery-filter-empty');
  const count=document.getElementById('delivery-count');
  const apply=()=>{let shown=0;rows.forEach(row=>{const date=row.dataset.createdDate||'';const needle=(search?.value||'').toLowerCase().trim();const matches=(!needle||(row.dataset.search||'').includes(needle))&&(!from?.value||date>=from.value)&&(!to?.value||date<=to.value);row.hidden=!matches;if(matches)shown++});if(empty)empty.hidden=shown!==0;if(count)count.textContent=`Showing ${shown} of ${rows.length} shipments on this page`;};
  search?.addEventListener('input',apply);from?.addEventListener('change',apply);to?.addEventListener('change',apply);apply();
  const loading=document.getElementById('delivery-loading');document.getElementById('delivery-filters')?.addEventListener('submit',()=>{if(loading)loading.hidden=false});document.querySelectorAll('nav[aria-label="Shipment pages"] a').forEach(link=>link.addEventListener('click',()=>{if(link.getAttribute('aria-disabled')!=='true'&&loading)loading.hidden=false}));
  document.querySelectorAll('[data-delivery-transition]').forEach(form=>form.addEventListener('submit',event=>{const next=form.dataset.nextStatus;if(!window.confirm(`Update this shipment to ${next.replaceAll('_',' ').toLowerCase()}?`))event.preventDefault()}));
});
</script>
</body></html>
